def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    section: dict[str, str] | None = None
    current_key: str | None = None

    for lineno, raw in enumerate(text.splitlines(), 1):
        stripped = raw.strip()

        # Blank lines and comments are ignored, and end a continuation.
        if not stripped or stripped[0] in "#;":
            current_key = None
            continue

        # An indented line continues the current value, if there is one.
        if raw[0].isspace() and current_key is not None and section is not None:
            section[current_key] += "\n" + stripped
            continue

        if stripped.startswith("["):
            if not stripped.endswith("]") or len(stripped) < 2:
                raise ParseError(lineno, "invalid section header")
            name = stripped[1:-1].strip()
            if not name:
                raise ParseError(lineno, "empty section name")
            section = sections.setdefault(name, {})
            current_key = None
            continue

        # Split at whichever delimiter appears first.
        positions = [
            position
            for position in (stripped.find("="), stripped.find(":"))
            if position != -1
        ]
        if not positions:
            raise ParseError(lineno, "expected a section header or 'key = value'")
        delimiter = min(positions)

        key = stripped[:delimiter].strip().lower()
        value = stripped[delimiter + 1 :].strip()
        if not key:
            raise ParseError(lineno, "empty key")
        if section is None:
            raise ParseError(lineno, "key before any section")

        section[key] = value
        current_key = key

    return _interpolate(sections)


def _interpolate(
    sections: dict[str, dict[str, str]],
) -> dict[str, dict[str, str]]:
    """Interpolate every value, preserving first-appearance order."""
    cache: dict[tuple[str, str], str] = {}
    result: dict[str, dict[str, str]] = {}
    for section_name, values in sections.items():
        result[section_name] = {
            key: _resolve(section_name, key, sections, cache, [])
            for key in values
        }
    return result


def _resolve(
    section_name: str,
    key: str,
    sections: dict[str, dict[str, str]],
    cache: dict[tuple[str, str], str],
    stack: list[tuple[str, str]],
) -> str:
    """Return one interpolated value, detecting cycles."""
    identity = (section_name, key)
    if identity in cache:
        return cache[identity]
    if identity in stack:
        chain = " -> ".join(f"{name}:{item}" for name, item in stack + [identity])
        raise InterpolationError(f"cycle in interpolation: {chain}")

    values = sections.get(section_name)
    if values is None:
        raise InterpolationError(f"missing section {section_name!r}")
    if key not in values:
        raise InterpolationError(
            f"missing key {key!r} in section {section_name!r}"
        )

    stack.append(identity)
    try:
        value = _interpolate_text(values[key], section_name, sections, cache, stack)
    finally:
        stack.pop()

    cache[identity] = value
    return value


def _interpolate_text(
    text: str,
    section_name: str,
    sections: dict[str, dict[str, str]],
    cache: dict[tuple[str, str], str],
    stack: list[tuple[str, str]],
) -> str:
    """Expand references in ``text`` in a single pass."""
    parts: list[str] = []
    index = 0
    length = len(text)

    while index < length:
        character = text[index]
        if character != "$":
            parts.append(character)
            index += 1
            continue

        if index + 1 < length and text[index + 1] == "$":
            # A literal dollar sign; never scanned for references again.
            parts.append("$")
            index += 2
            continue

        if index + 1 < length and text[index + 1] == "{":
            end = text.find("}", index + 2)
            if end != -1:
                reference = text[index + 2 : end]
                if ":" in reference:
                    target_section, target_key = reference.split(":", 1)
                else:
                    target_section, target_key = section_name, reference
                parts.append(
                    _resolve(
                        target_section,
                        target_key.lower(),
                        sections,
                        cache,
                        stack,
                    )
                )
                index = end + 1
                continue

        # Any other dollar sign (including an unterminated ``${``).
        parts.append("$")
        index += 1

    return "".join(parts)

