"""Scratch tests for devkit.ini (kept outside the project)."""

import sys

sys.path.insert(0, "/private/tmp/tmp_zhdllvc/pete/projects/devkit")

from devkit.ini import InterpolationError, ParseError, parse

passes = 0
failures = []


def check(name, func):
    global passes
    try:
        func()
    except Exception as exc:  # noqa: BLE001 - scratch harness
        failures.append((name, exc))
        print(f"FAIL {name}: {exc!r}")
    else:
        passes += 1
        print(f"ok   {name}")


def eq(actual, expected):
    assert actual == expected, f"actual={actual!r} expected={expected!r}"


def expect_parse_error(text, lineno):
    try:
        parse(text)
    except ParseError as exc:
        eq(exc.lineno, lineno)
    else:
        raise AssertionError("expected ParseError")


def expect_interp_error(text):
    try:
        parse(text)
    except InterpolationError:
        return
    else:
        raise AssertionError("expected InterpolationError")


# --- parsing basics -------------------------------------------------------


def test_empty_input():
    eq(parse(""), {})
    eq(parse("\n\n  \n"), {})


def test_comments_only():
    eq(parse("# a\n; b\n  # c\n\t; d\n"), {})


def test_basic():
    text = (
        "# comment\n"
        "; another\n"
        "\n"
        "[server]\n"
        "host = example.com\n"
        "port: 8080\n"
        "empty =\n"
        "empty_colon:\n"
        "  # indented comment\n"
        "[ client ]\n"
        "name   =   Bob  \n"
    )
    eq(
        parse(text),
        {
            "server": {
                "host": "example.com",
                "port": "8080",
                "empty": "",
                "empty_colon": "",
            },
            "client": {"name": "Bob"},
        },
    )


def test_section_whitespace_and_case():
    eq(
        parse("  [ spaced NAME ]  \n  key = v\n[other]\n"),
        {"spaced NAME": {"key": "v"}, "other": {}},
    )


def test_empty_section_body():
    eq(parse("[s]\n[t]\nk = v\n"), {"s": {}, "t": {"k": "v"}})


def test_delimiters_first_occurrence():
    text = (
        "[s]\n"
        "a=b=c\n"
        "b: c=d\n"
        "url = http://example.com:8080/x\n"
        "wide: a:b:c\n"
        "e:\n"
        "f=\n"
    )
    eq(
        parse(text),
        {
            "s": {
                "a": "b=c",
                "b": "c=d",
                "url": "http://example.com:8080/x",
                "wide": "a:b:c",
                "e": "",
                "f": "",
            }
        },
    )


def test_inline_hash_and_semicolon_are_values():
    eq(parse("[s]\na = x # y\nb = x ; y\n"), {"s": {"a": "x # y", "b": "x ; y"}})


def test_duplicate_sections_and_keys():
    text = (
        "[a]\n"
        "x = 1\n"
        "y = 2\n"
        "[b]\n"
        "q = 9\n"
        "[a]\n"
        "z = 3\n"
        "x = 4\n"
    )
    result = parse(text)
    eq(list(result), ["a", "b"])
    eq(list(result["a"]), ["x", "y", "z"])
    eq(result["a"]["x"], "4")
    eq(result["a"]["y"], "2")
    eq(result["a"]["z"], "3")


def test_empty_value_continuation():
    eq(parse("[s]\na =\n  cont\n"), {"s": {"a": "\ncont"}})


def test_continuations_chain():
    text = (
        "[s]\n"
        "a = first\n"
        "  second\n"
        "\t\tthird\n"
        "b = next\n"
        "  b = not a key\n"
    )
    eq(
        parse(text),
        {"s": {"a": "first\nsecond\nthird", "b": "next\nb = not a key"}},
    )


def test_continuation_multiple_after_empty_value():
    eq(parse("[s]\na =\n  one\n  two\n"), {"s": {"a": "\none\ntwo"}})


def test_continuation_broken_by_blank():
    text = "[s]\na = one\n  two\n\n  b = three\n"
    eq(parse(text), {"s": {"a": "one\ntwo", "b": "three"}})


def test_continuation_broken_by_comment():
    text = "[s]\na = one\n  two\n  ; comment\n  b = three\n"
    eq(parse(text), {"s": {"a": "one\ntwo", "b": "three"}})


def test_continuation_broken_by_section():
    text = "[s]\na = one\n  two\n[t]\n  b = three\n"
    eq(parse(text), {"s": {"a": "one\ntwo"}, "t": {"b": "three"}})


def test_continuation_broken_by_new_key():
    text = "[s]\na = one\n  two\nb = three\n  four\n"
    eq(parse(text), {"s": {"a": "one\ntwo", "b": "three\nfour"}})


def test_indented_section_after_key_is_continuation():
    text = "[s]\na = one\n  [t]\n"
    eq(parse(text), {"s": {"a": "one\n[t]"}})


def test_indented_key_after_key_is_continuation():
    eq(parse("[s]\na = one\n  b = two\n"), {"s": {"a": "one\nb = two"}})


def test_parse_error_indented_garbage_no_active_key():
    expect_parse_error("[s]\na = 1\n\n  not a key line\n", 4)


def test_parse_error_key_before_section():
    expect_parse_error("key = value\n[s]\n", 1)
    expect_parse_error("\n  key: value\n[s]\n", 2)


def test_parse_error_garbage_line():
    expect_parse_error("[s]\na = 1\ngarbage\n", 3)


def test_parse_error_empty_key():
    expect_parse_error("[s]\n= value\n", 2)
    expect_parse_error("[s]\n: value\n", 2)
    expect_parse_error("[s]\n=\n", 2)


def test_parse_error_malformed_section():
    expect_parse_error("[s]\na = 1\n[foo\n", 3)
    expect_parse_error("[s]\na = 1\n[foo] trailing\n", 3)
    expect_parse_error("[s]\na = 1\n[]\n", 3)


def test_crlf():
    text = "[s]\r\na = 1\r\n  two\r\nb: 2\r\n"
    eq(parse(text), {"s": {"a": "1\ntwo", "b": "2"}})


# --- interpolation --------------------------------------------------------


def test_interp_same_section():
    eq(
        parse("[s]\na = hello\nb = ${a} world\n"),
        {"s": {"a": "hello", "b": "hello world"}},
    )


def test_interp_key_case_insensitive():
    eq(
        parse("[s]\nName = Bob\ngreeting = hi ${NAME}\n"),
        {"s": {"name": "Bob", "greeting": "hi Bob"}},
    )


def test_interp_cross_section():
    eq(
        parse("[a]\nx = ${b:y}!\n[b]\ny = Y\n"),
        {"a": {"x": "Y!"}, "b": {"y": "Y"}},
    )


def test_interp_cross_section_key_case():
    eq(
        parse("[S2]\nX = value\n[s]\na = ${S2:X}\n"),
        {"S2": {"x": "value"}, "s": {"a": "value"}},
    )


def test_interp_multiple_and_edges():
    text = (
        "[s]\n"
        "x = A\n"
        "y = B\n"
        "starts = ${x} middle\n"
        "ends = middle ${y}\n"
        "many = ${x}-${y}-${x}\n"
        "only = ${y}\n"
    )
    result = parse(text)
    eq(result["s"]["starts"], "A middle")
    eq(result["s"]["ends"], "middle B")
    eq(result["s"]["many"], "A-B-A")
    eq(result["s"]["only"], "B")


def test_interp_nested_and_forward():
    text = (
        "[s]\n"
        "c = ${b}z\n"
        "b = ${a}y\n"
        "a = x\n"
    )
    eq(
        parse(text),
        {"s": {"c": "xyz", "b": "xy", "a": "x"}},
    )


def test_interp_nested_cross_section():
    text = "[a]\nx = ${b:y}\n[b]\ny = ${c:z}\n[c]\nz = deep\n"
    eq(
        parse(text),
        {
            "a": {"x": "deep"},
            "b": {"y": "deep"},
            "c": {"z": "deep"},
        },
    )


def test_interp_local_shadows_other_section():
    text = "[s1]\nx = one\ny = ${x}\n[s2]\nx = two\n"
    eq(parse(text), {"s1": {"x": "one", "y": "one"}, "s2": {"x": "two"}})


def test_dollar_dollar():
    text = (
        "[s]\n"
        "a = $$5\n"
        "b = $${a}\n"
        "c = $$ $$\n"
        "d = $$$$\n"
        "e = $$${a}\n"
    )
    result = parse(text)
    eq(result["s"]["a"], "$5")
    eq(result["s"]["b"], "${a}")
    eq(result["s"]["c"], "$ $")
    eq(result["s"]["d"], "$$")
    eq(result["s"]["e"], "$5")


def test_dollar_dollar_in_referenced_value():
    text = "[s]\na = $$literal\nb = <${a}>\n"
    eq(parse(text), {"s": {"a": "$literal", "b": "<$literal>"}})


def test_dollar_dollar_output_not_reinterpolated():
    text = "[s]\nx = $${y}\ny = hi\nz = ${x}\nw = ${x}${y}\n"
    eq(
        parse(text),
        {"s": {"x": "${y}", "y": "hi", "z": "${y}", "w": "${y}hi"}},
    )


def test_other_dollars():
    text = (
        "[s]\n"
        "a = $x\n"
        "b = end$\n"
        "c = $ {x}\n"
        "d = a $ b\n"
        "e = abc ${x\n"
        "f = ${x} $${x}\n"
        "x = X\n"
    )
    result = parse(text)
    eq(result["s"]["a"], "$x")
    eq(result["s"]["b"], "end$")
    eq(result["s"]["c"], "$ {x}")
    eq(result["s"]["d"], "a $ b")
    eq(result["s"]["e"], "abc ${x")
    eq(result["s"]["f"], "X ${x}")


def test_urls_and_colons_untouched():
    text = "[s]\nurl = http://example.com:8080/x\ncopy = ${url}\n"
    eq(
        parse(text),
        {
            "s": {
                "url": "http://example.com:8080/x",
                "copy": "http://example.com:8080/x",
            }
        },
    )


def test_interp_direct_cycle():
    expect_interp_error("[s]\na = ${a}\n")


def test_interp_indirect_cycle():
    expect_interp_error("[s]\na = ${b}\nb = ${c}\nc = ${a}\n")


def test_interp_cross_section_cycle():
    expect_interp_error("[a]\nx = ${b:y}\n[b]\ny = ${a:x}\n")


def test_interp_missing_key():
    expect_interp_error("[s]\na = ${nope}\n")


def test_interp_missing_section():
    expect_interp_error("[s]\na = ${nope:x}\n")
    expect_interp_error("[s]\na = ${S2:x}\n[S2]\nx = 1\n")


def test_interp_empty_references():
    expect_interp_error("[s]\na = ${}\n")
    expect_interp_error("[s]\na = ${:key}\n")
    expect_interp_error("[s]\na = ${sec:}\n")
    expect_interp_error("[s]\na = ${:}\n")


def test_interpolation_error_is_value_error():
    try:
        parse("[s]\na = ${missing}\n")
    except InterpolationError as exc:
        assert isinstance(exc, ValueError)
    else:
        raise AssertionError("expected InterpolationError")


def test_parse_error_lineno_attribute():
    try:
        parse("[s]\ngarbage\n")
    except ParseError as exc:
        eq(exc.lineno, 2)
        assert "line 2" in str(exc)
    else:
        raise AssertionError("expected ParseError")


def test_returned_values_are_plain_strings():
    result = parse("[s]\na = $$x\nb = ${a}\n")
    eq(result, {"s": {"a": "$x", "b": "$x"}})
    eq(type(result["s"]["a"]), str)


def test_order_preserved_with_interpolation():
    text = "[z]\nk3 = 3\nk1 = 1\n[a]\nk2 = 2\n[z]\nk4 = 4\n"
    result = parse(text)
    eq(list(result), ["z", "a"])
    eq(list(result["z"]), ["k3", "k1", "k4"])


def main():
    tests = [
        (name, value)
        for name, value in sorted(globals().items())
        if name.startswith("test_") and callable(value)
    ]
    for name, func in tests:
        check(name, func)

    print(f"\n{passes} passed, {len(failures)} failed, {len(tests)} total")
    if failures:
        for name, exc in failures:
            print(f"  FAILED {name}: {exc!r}")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

